+    auto ImpDescs = fromASTModCxt(ASTCxt)->getImportSection().getContent();
+    auto MemTypes = fromASTModCxt(ASTCxt)->getMemorySection().getContent();
     uint32_t ExtIdx = fromExpTypeCxt(Cxt)->getExternalIndex();
