-    const auto &MemTypes =
-        fromASTModCxt(ASTCxt)->getMemorySection().getContent();
-    if (ExtIdx >= MemTypes.size()) {
+    // Get the memory type.
+    if (ExtIdx < ImpMems.size()) {
